(()=>{if(!matchMedia('(hover: hover) and (pointer: fine)').matches||matchMedia('(prefers-reduced-motion: reduce)').matches)return;let current=null;const selector='.metric,.course-card,.academy-course,.person,.room-card,.reward';const reset=el=>{el?.style.setProperty('--tilt-x','0deg');el?.style.setProperty('--tilt-y','0deg');};document.addEventListener('pointermove',e=>{const card=e.target.closest?.(selector);if(current&&current!==card)reset(current);current=card;if(!card)return;const r=card.getBoundingClientRect();card.style.setProperty('--tilt-x',((.5-(e.clientY-r.top)/r.height)*3).toFixed(2)+'deg');card.style.setProperty('--tilt-y',(((e.clientX-r.left)/r.width-.5)*3).toFixed(2)+'deg');},{passive:true});document.addEventListener('pointerleave',()=>{reset(current);current=null;});addEventListener('blur',()=>{reset(current);current=null;});})();
